@startuml
class Client {
  +nin : string
  +tin : string
  +name : string
  +address : string
}

class BicycleModel {
  +name : string
  +type : BicycleType
  +gears : int
}

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Bicycle {
  +id_number : string
}

class Store {
  +name : string
  +address : string
}

class Reservation {
  +pickup_date : date
}

class Rental {
  +return_date : date
}

Client "1..*" -- "0..*" Reservation : makes
BicycleModel "1" -- "0..*" Reservation : requested in
Store "1" -- "0..*" Reservation : pickup location

Client "1" -- "0..*" Rental : makes
Bicycle "1" -- "0..*" Rental : is rented in
Store "1" -- "0..*" Rental : return location

BicycleModel "1" -- "1..*" Bicycle : defines
@enduml

